"use client";
import { partnerLinks } from "@/lib/partnerLinks";
import React, { useEffect, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faHeadset,
  faListCheck,
  faPlaneCircleCheck,
} from "@fortawesome/free-solid-svg-icons";
import Destinations from "./destinations";
import BlogTeasers from "./blog-teasers";

const tabs = [
  { id: "enhancements", label: "Enhancements" },
  { id: "profile", label: "Your Profile" },
  { id: "rewards", label: "Rewards Program" },
  { id: "next", label: "What's Next?" },
  { id: "share", label: "Share Your Feedback" },
];

const enhancements = [
  {
    title: "Trip Protection",
    body: "Protect yourself if your plans need to be altered with comprehensive travel insurance.",
    image: "/images/travelInsurance.webp",
    href: "/cancellation-policy/travel-insurance",
    cta: "Discover",
  },
  {
    title: "Visa",
    body: "Obtain your e-Visa quickly and simplify your travel formalities before you fly.",
    image: "/images/visa.jpg",
    href: "/after-your-booking/visa",
    cta: "Discover",
    blank: true,
  },
];

const profileCards = [
  {
    icon: faPlaneCircleCheck,
    title: "Check your trip information",
    body: "Keep all your trip details in one convenient spot. Your itinerary, dates, and more are easily accessible in your TravelShop Booking account, serving as your personal travel organizer for your adventure.",
  },
  {
    icon: faListCheck,
    title: "Retrieve your reservation details",
    body: "Looking for your booking confirmation or need to make changes? Your TravelShop Booking account lets you request airport transfers, add travel insurance, and much more.",
  },
  {
    icon: faHeadset,
    title: "Reach out for help, anytime",
    body: "Questions are always welcome! Connect with your adventure operator or our Travel Experts directly through your account. Enjoy 24/7 customer service before, during, and after your tour.",
  },
];

const provides = [
  {
    title: "Hotel Vouchers",
    image: "/images/voucher.png",
    body: "Once your booking is confirmed, you will receive a hotel voucher that includes all necessary details for your stay — hotel name, address, contact details, room type, check-in and check-out dates, and any special arrangements such as early check-in or late check-out. The voucher also contains booking references and guidelines for a smooth check-in process.",
  },
  {
    title: "Restaurant Vouchers",
    image: "/images/restaurantVoucher.jpg",
    body: "For travel packages that include meal services, restaurant vouchers will be issued. These outline meal times, dining locations, and specific inclusions such as buffet or à la carte options. If dietary preferences were made during booking, they will be noted. Certain packages may also include dining credits or discounts at partner restaurants.",
  },
  {
    title: "Itinerary Tour Details",
    image: "/images/tourIternary.jpg",
    body: "A comprehensive tour itinerary will be provided, detailing the day-to-day schedule, destinations, and activities planned. This document specifies meeting points, departure times, inclusions (such as guided tours, entrance fees, and transportation), and any necessary preparation requirements.",
  },
  {
    title: "Invoice Information",
    image: "/images/invoiceInfos.webp",
    body: "A detailed invoice will be sent to your email upon booking confirmation, including a breakdown of costs, taxes, and service charges. It will also specify payment methods, transaction details, and any outstanding balances. Travelers may use this invoice for reimbursement or record-keeping.",
  },
  {
    title: "Pick-Up Details",
    image: "/images/pickup.webp",
    body: "For transfers and transportation services, pick-up details will be shared well in advance — exact pick-up location, time, assigned driver or guide contact information, and vehicle specifications. Any special instructions regarding airport transfers or hotel pick-ups will be provided for seamless coordination.",
  },
];

const needs = [
  {
    title: "Visa Information Check",
    image: "/images/checkvisa.png",
    body: "It is the traveler's responsibility to verify visa requirements for their destination. Visa policies vary by country, so check with the relevant embassy or consulate well ahead of your trip. We recommend our visa assistance services for guidance. Some destinations may also require transit visas for layovers.",
  },
  {
    title: "International & Domestic Tickets",
    image: "/images/domestic.jpg",
    body: "All travelers must confirm their international and domestic flight tickets before departure — double-checking dates, times, baggage allowances, and layover durations. If your package includes airport transfers, sharing your flight details ensures timely pick-up. Notify us of any flight changes as soon as possible.",
  },
  {
    title: "Passport Information",
    image: "/images/passportinfo.jpg",
    body: "A valid passport is mandatory for international travel. Most countries require passports to be valid for at least six months beyond the intended return date. Ensure all passport details match your booking to avoid complications at check-in or immigration. Submit your passport details in advance if visa processing requires it.",
  },
  {
    title: "Stay Details: Hotel Type & Location",
    image: "/images/hotelType.webp",
    body: "Confirm your hotel preferences, including the type of accommodation — standard, luxury, boutique, or budget — and location preferences such as city center, beachfront, or countryside. This helps us plan logistics like pick-up and drop-off. Let us know any specific requests such as adjoining rooms or accessibility features.",
  },
];

const AfterYourBooking = () => {
  const [active, setActive] = useState(tabs[0].id);

  useEffect(() => {
    const sections = tabs
      .map((t) => document.getElementById(t.id))
      .filter((el): el is HTMLElement => el !== null);

    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) setActive(visible.target.id);
      },
      { rootMargin: "-40% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );

    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/nature.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              After-Sales Services
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Your adventure is booked — here&apos;s what&apos;s next
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              We&apos;ve made it simple to get everything sorted in one place.
              From travel insurance to flights and visas, TravelShop Booking has
              you covered so you can focus on the thrill ahead.
            </p>
          </div>
        </div>
      </section>

      {/* Sticky tab nav */}
      <div className="tw-sticky tw-top-0 tw-z-30 tw-bg-white/90 tw-backdrop-blur tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-4 md:tw-px-8">
          <nav
            className="tw-flex tw-gap-1.5 tw-overflow-x-auto tw-py-3"
            style={{ scrollbarWidth: "none" }}
          >
            {tabs.map((tab) => (
              <a
                key={tab.id}
                href={`#${tab.id}`}
                aria-current={active === tab.id ? "true" : undefined}
                className={`tw-whitespace-nowrap tw-rounded-full tw-px-4 tw-py-2 tw-text-[14px] tw-font-semibold tw-no-underline tw-transition-colors ${
                  active === tab.id
                    ? "tw-bg-[#854ec9] tw-text-white"
                    : "tw-text-[#5d556c] hover:tw-bg-[#faf9fc] hover:tw-text-[#14101c]"
                }`}
              >
                {tab.label}
              </a>
            ))}
          </nav>
        </div>
      </div>

      {/* Enhancements */}
      <section
        id="enhancements"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-rounded-3xl tw-bg-[#faf8ff] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-7 md:tw-p-10">
            <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-3 tw-gap-7 lg:tw-gap-8 tw-items-stretch">
              <div className="tw-flex tw-flex-col tw-justify-center">
                <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                  Enhancements
                </span>
                <h2 className="tw-mt-2 tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                  Finish Your Journey
                </h2>
                <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                  Find the best flight deals, secure comprehensive travel
                  insurance, and apply for your visa — all conveniently with
                  TravelShop Booking.
                </p>
              </div>
              {enhancements.map((card) => (
                <div
                  key={card.title}
                  className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
                >
                  <img
                    src={card.image}
                    alt={card.title}
                    loading="lazy"
                    className="tw-h-44 tw-w-full tw-object-cover"
                  />
                  <div className="tw-flex tw-flex-col tw-flex-1 tw-p-5">
                    <h3 className="tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
                      {card.title}
                    </h3>
                    <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                      {card.body}
                    </p>
                    <a
                      href={card.href}
                      target={card.blank ? "_blank" : undefined}
                      rel={card.blank ? "noopener noreferrer" : undefined}
                      className="tw-mt-4 tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-self-start tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[14px] tw-px-5 tw-py-2.5 tw-rounded-full tw-no-underline tw-transition-colors"
                    >
                      {card.cta} <span aria-hidden="true">→</span>
                    </a>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Your Profile */}
      <section
        id="profile"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-max-w-[760px]">
            <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
              Your Profile
            </span>
            <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Explore your TravelShop Booking profile
            </h2>
            <p className="tw-mt-4 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
              Before you dig out the stapler and start printing documents, did
              you know your TravelShop Booking account is your one-stop hub for
              all your travel needs? Go paperless and explore the handy features
              of your account.
            </p>
          </div>

          <div className="tw-mt-8 tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {profileCards.map((card) => (
              <div
                key={card.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <div className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={card.icon} className="tw-text-2xl" />
                </div>
                <h3 className="tw-mt-4 tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                  {card.title}
                </h3>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.body}
                </p>
              </div>
            ))}
          </div>

          <div className="tw-mt-8 tw-text-center">
            <a
              href={partnerLinks.login}
              target="_blank"
              rel="noopener noreferrer"
              className="tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
            >
              Go to My Account <span aria-hidden="true">→</span>
            </a>
          </div>
        </div>
      </section>

      {/* Rewards */}
      <section id="rewards" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Rewards Program
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                A small token from us
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We&apos;re deeply passionate about the spirit of adventure and
                take great joy in celebrating every traveler who embarks on an
                exciting journey — including you! As a heartfelt token of our
                gratitude for choosing to travel with us, we&apos;re delighted
                to offer you Travel Credits. These credits are our way of saying
                thank you and ensuring your next journey is even more rewarding.
              </p>
              <a
                href="/after-your-booking/invite"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Check My Travel Credits <span aria-hidden="true">→</span>
              </a>
            </div>
            <div>
              <img
                src="/images/thankYou.jpg"
                alt="Thank you"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* What's Next */}
      <section
        id="next"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
              What&apos;s Next?
            </span>
            <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              What TravelShop Booking Provides
            </h2>
          </div>

          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {provides.map((card) => (
              <div
                key={card.title}
                className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
              >
                <img
                  src={card.image}
                  alt={card.title}
                  loading="lazy"
                  className="tw-h-44 tw-w-full tw-object-cover"
                />
                <div className="tw-flex tw-flex-col tw-flex-1 tw-p-6">
                  <h3 className="tw-text-[17px] tw-font-bold tw-text-[#14101c] tw-m-0">
                    {card.title}
                  </h3>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                    {card.body}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <h3 className="tw-mt-14 tw-mb-8 tw-text-center tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
            What We Need from Travelers
          </h3>
          <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-5 lg:tw-gap-6">
            {needs.map((card) => (
              <div
                key={card.title}
                className="tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] hover:tw-shadow-lg tw-transition-shadow tw-duration-200"
              >
                <img
                  src={card.image}
                  alt={card.title}
                  loading="lazy"
                  className="tw-h-40 tw-w-full tw-object-cover"
                />
                <div className="tw-flex tw-flex-col tw-flex-1 tw-p-5">
                  <h4 className="tw-text-[16px] tw-font-bold tw-text-[#14101c] tw-m-0">
                    {card.title}
                  </h4>
                  <p className="tw-mt-2 tw-mb-0 tw-text-[13px] tw-leading-[1.6] tw-text-[#5d556c]">
                    {card.body}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <p className="tw-mt-10 tw-mb-0 tw-text-center tw-text-[14px] tw-font-semibold tw-text-[#5d556c]">
            *For any questions or further assistance, feel free to contact our
            support team. Our goal is to ensure your travel experience is as
            seamless and enjoyable as possible.
          </p>
        </div>
      </section>

      {/* Share Feedback */}
      <section id="share" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/review.webp"
                alt="Share your feedback"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Share Your Feedback
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Share your feedback with us
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                At TravelShop Booking, we&apos;re passionate about sending
                travelers like you on unforgettable, life-enriching journeys!
              </p>
              <p className="tw-mt-3 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We take pride in collaborating with top-tier operators who
                provide world-class travel experiences. If your guide made your
                adventure unforgettable, let them know — they deserve the
                recognition! Or, if there&apos;s room for improvement, share
                your thoughts to help make future adventures even more epic.
              </p>
              <a
                href="https://www.trustpilot.com/review/travelshopbooking.com"
                target="_blank"
                rel="noopener noreferrer"
                className="tw-mt-6 tw-inline-flex tw-items-center tw-gap-2 tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-6 tw-py-3.5 tw-rounded-full tw-no-underline tw-transition-colors"
              >
                Share your thoughts <span aria-hidden="true">→</span>
              </a>
            </div>
          </div>
        </div>
      </section>

      <BlogTeasers />
      <Destinations />
    </main>
  );
};

export default AfterYourBooking;
